{
  "code": "import pytest
import impl


def test_usd_exact():
    """USD amount with exact 2 decimal places."""
    assert impl.format_amount("1.23", "USD", {'USD': 2}) == "1.23"


def test_usd_padded():
    """USD integer gets zero-padded to 2 decimals."""
    assert impl.format_amount("1", "USD", {'USD': 2}) == "1.00"


def test_jpy_no_decimals():
    """JPY (0 decimals) strips fractional part."""
    assert impl.format_amount("1234.5", "JPY", {'JPY': 0}) == "1234"


def test_round_half_even_up():
    """Banker's rounding: 2.675 → 2.68 (even)."""
    assert impl.format_amount("2.675", "USD", {'USD': 2}) == "2.68"


def test_round_half_even_down():
    """Banker's rounding: 2.665 → 2.66 (even)."""
    assert impl.format_amount("2.665", "USD", {'USD': 2}) == "2.66"


def test_negative_rounding():
    """Negative amounts round symmetrically."""
    assert impl.format_amount("-2.675", "USD", {'USD': 2}) == "-2.68"


def test_zero_with_decimals():
    """Zero formatted with decimal places."""
    assert impl.format_amount("0", "USD", {'USD': 2}) == "0.00"


def test_zero_no_decimals():
    """Zero formatted without decimals."""
    assert impl.format_amount("0", "JPY", {'JPY': 0}) == "0"


def test_negative_zero():
    """Negative zero is unsigned: -0.004 USD → 0.00."""
    assert impl.format_amount("-0.004", "USD", {'USD': 2}) == "0.00"


def test_scientific_notation():
    """Scientific notation: 1E+2 = 100."""
    assert impl.format_amount("1E+2", "USD", {'USD': 2}) == "100.00"


def test_whitespace():
    """Whitespace in amount is accepted."""
    assert impl.format_amount(" 123.45 ", "USD", {'USD': 2}) == "123.45"


def test_large_number():
    """Large numbers displayed without exponent notation."""
    assert impl.format_amount("1234567890.123", "USD", {'USD': 2}) == "1234567890.12"


def test_bhd_three_decimals():
    """BHD with 3 decimal places."""
    assert impl.format_amount("1.2345", "BHD", {'BHD': 3}) == "1.235"


def test_clf_four_decimals():
    """CLF with 4 decimal places."""
    assert impl.format_amount("1.23456", "CLF", {'CLF': 4}) == "1.2346"


def test_unknown_currency():
    """Unknown currency raises KeyError."""
    with pytest.raises(KeyError):
        impl.format_amount("123.45", "EUR", {'USD': 2})


def test_currency_before_amount():
    """Currency lookup happens before amount validation."""
    with pytest.raises(KeyError):
        impl.format_amount("invalid", "EUR", {'USD': 2})


def test_empty_string():
    """Empty string raises ValueError."""
    with pytest.raises(ValueError):
        impl.format_amount("", "USD", {'USD': 2})


def test_invalid_format():
    """Invalid format (multiple dots) raises ValueError."""
    with pytest.raises(ValueError):
        impl.format_amount("1.2.3", "USD", {'USD': 2})


def test_infinity():
    """Infinity raises ValueError."""
    with pytest.raises(ValueError):
        impl.format_amount("Infinity", "USD", {'USD': 2})


def test_nan():
    """NaN raises ValueError."""
    with pytest.raises(ValueError):
        impl.format_amount("NaN", "USD", {'USD': 2})"
}
